//! `/api/v1` operations of `docs/rewrite/api/12-reference.yaml`: the
//! reference lists of §8b (D001–D004). The data the PHP took from packages
//! is embedded from `reference/*.json`, generated from the PHP sources:
//! countries from `rinvex/countries` (`Country::getTranslations`), languages
//! from `matriphe/iso-639`, timezones from `DateTimeZone::listIdentifiers()`
//! plus `GMT`, currency names from `lang/en/currencies.php`.
// Generated by docs/rewrite/tools/gen_api.py; the handlers are filled in by hand.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use crate::db::id::Id;
use crate::entities::currencies;
use crate::error::ApiResult;
use crate::http::auth::Auth;
use crate::http::json::Json;
use crate::http::state::AppState;
use axum::extract::State;
use chrono::{Offset, TimeZone, Utc};
use sea_orm::{EntityTrait, QueryOrder};
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;
use utoipa_axum::router::OpenApiRouter;
use utoipa_axum::routes;

#[derive(Serialize, ToSchema)]
pub struct Currency {
    #[schema(value_type = i64)]
    pub id: Id,
    /// ISO 4217 code as seeded in `currencies` (includes some retired codes).
    pub code: String,
    /// Name in the request locale (`lang/*/currencies.php`).
    pub name: String,
}

#[derive(Serialize, ToSchema)]
pub struct CurrencyList {
    pub data: Vec<Currency>,
}

#[derive(Serialize, ToSchema)]
pub struct Country {
    /// ISO 3166-1 alpha-2.
    pub code: String,
    /// Common name in the request locale.
    pub name: String,
}

#[derive(Serialize, ToSchema)]
pub struct CountryList {
    pub data: Vec<Country>,
}

#[derive(Serialize, ToSchema)]
pub struct Language {
    /// ISO 639-1.
    pub code: String,
    /// Name in the request locale.
    pub name: String,
    pub native_name: String,
}

#[derive(Serialize, ToSchema)]
pub struct LanguageList {
    pub data: Vec<Language>,
}

#[derive(Serialize, ToSchema)]
pub struct Timezone {
    pub id: String,
    /// Computed. Current offset from UTC in minutes (the page shows it as `GMT/UTC - 03:00`).
    pub utc_offset: i64,
}

#[derive(Serialize, ToSchema)]
pub struct TimezoneList {
    pub data: Vec<Timezone>,
}

/// A country of `reference/countries.json`: its common names keyed by
/// ISO 639-3 language (`eng` always present).
#[derive(Deserialize)]
struct CountryData {
    code: String,
    names: BTreeMap<String, String>,
}

/// A language of `reference/languages.json` (`ISO639::allLanguages()`).
#[derive(Deserialize)]
struct LanguageData {
    code: String,
    name: String,
    native_name: String,
}

fn countries() -> &'static [CountryData] {
    static DATA: OnceLock<Vec<CountryData>> = OnceLock::new();
    DATA.get_or_init(|| serde_json::from_str(include_str!("reference/countries.json")).expect("countries.json"))
}

fn languages() -> &'static [LanguageData] {
    static DATA: OnceLock<Vec<LanguageData>> = OnceLock::new();
    DATA.get_or_init(|| serde_json::from_str(include_str!("reference/languages.json")).expect("languages.json"))
}

fn timezones() -> &'static [String] {
    static DATA: OnceLock<Vec<String>> = OnceLock::new();
    DATA.get_or_init(|| serde_json::from_str(include_str!("reference/timezones.json")).expect("timezones.json"))
}

fn currency_names() -> &'static BTreeMap<String, String> {
    static DATA: OnceLock<BTreeMap<String, String>> = OnceLock::new();
    DATA.get_or_init(|| serde_json::from_str(include_str!("reference/currencies.json")).expect("currencies.json"))
}

/// `__('currencies.'.$code)`: only `lang/en/currencies.php` exists, so every
/// locale gets the English name (Laravel's fallback locale), and an unknown
/// code gets the key itself.
pub fn currency_name(code: &str) -> String {
    currency_names().get(code).cloned().unwrap_or_else(|| format!("currencies.{code}"))
}

/// The ISO 639-3 code `rinvex/countries` keys its names by, for an app
/// locale (`pt_BR` → `por`, `zh_TW` → `zho`).
fn iso639_3(locale: &str) -> &'static str {
    match locale.split(['_', '-']).next().unwrap_or("en") {
        "ar" => "ara",
        "bn" => "ben",
        "ca" => "cat",
        "da" => "dan",
        "de" => "deu",
        "el" => "ell",
        "es" => "spa",
        "fr" => "fra",
        "he" => "heb",
        "hi" => "hin",
        "it" => "ita",
        "ja" => "jpn",
        "ml" => "mal",
        "nl" => "nld",
        "nn" => "nno",
        "pa" => "pan",
        "pl" => "pol",
        "pt" => "por",
        "ro" => "ron",
        "ru" => "rus",
        "sv" => "swe",
        "te" => "tel",
        "tr" => "tur",
        "ur" => "urd",
        "vi" => "vie",
        "zh" => "zho",
        _ => "eng",
    }
}

/// `country($code)->getTranslation($lang)['common']`, falling back to the
/// English common name when the data set has none in that language.
fn country_name<'a>(c: &'a CountryData, lang: &str) -> &'a str {
    c.names.get(lang).or_else(|| c.names.get("eng")).map_or(c.code.as_str(), String::as_str)
}

/// The current offset of `zone` from UTC, in minutes (0 for `GMT`/`UTC`).
fn utc_offset(zone: &str) -> i64 {
    zone.parse::<chrono_tz::Tz>()
        .map(|tz| i64::from(tz.offset_from_utc_datetime(&Utc::now().naive_utc()).fix().local_minus_utc()) / 60)
        .unwrap_or(0)
}

#[utoipa::path(
    get,
    path = "/reference/currencies",
    operation_id = "listReferenceCurrencies",
    tag = "Reference",
    summary = "All currencies, ordered by code",
    responses((status = 200, description = "The currencies.", body = CurrencyList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("user")), ("x-inventory" = json!([])), ("x-services" = json!([])))
)]
pub async fn list_reference_currencies(
    State(state): State<AppState>,
    Auth(_id): Auth,
) -> ApiResult<Json<CurrencyList>> {
    let rows = currencies::Entity::find()
        .order_by_asc(currencies::Column::Code)
        .order_by_asc(currencies::Column::Id)
        .all(&state.db)
        .await?;
    let data = rows.into_iter().map(|c| Currency { id: c.id, name: currency_name(&c.code), code: c.code }).collect();
    Ok(Json(CurrencyList { data }))
}

#[utoipa::path(
    get,
    path = "/reference/countries",
    operation_id = "listReferenceCountries",
    tag = "Reference",
    summary = "Countries, ordered by name",
    responses((status = 200, description = "The countries.", body = CountryList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("user")), ("x-inventory" = json!([])), ("x-services" = json!([])))
)]
pub async fn list_reference_countries(State(_state): State<AppState>, Auth(_id): Auth) -> ApiResult<Json<CountryList>> {
    let lang = iso639_3(&crate::i18n::current());
    let mut data: Vec<Country> =
        countries().iter().map(|c| Country { code: c.code.clone(), name: country_name(c, lang).to_owned() }).collect();
    crate::text::sort_by_collator(&mut data, |c| c.name.clone());
    Ok(Json(CountryList { data }))
}

#[utoipa::path(
    get,
    path = "/reference/languages",
    operation_id = "listReferenceLanguages",
    tag = "Reference",
    summary = "ISO 639-1 languages, ordered by name",
    responses((status = 200, description = "The languages.", body = LanguageList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("user")), ("x-inventory" = json!([])), ("x-services" = json!([])))
)]
pub async fn list_reference_languages(
    State(_state): State<AppState>,
    Auth(_id): Auth,
) -> ApiResult<Json<LanguageList>> {
    // `matriphe/iso-639` has English and native names only, and `lang/`
    // translates none of them: `name` is the English name in every locale.
    // Its one row without an ISO 639-1 code (Ladin) is left out.
    let mut data: Vec<Language> = languages()
        .iter()
        .filter(|l| !l.code.is_empty())
        .map(|l| Language { code: l.code.clone(), name: l.name.clone(), native_name: l.native_name.clone() })
        .collect();
    crate::text::sort_by_collator(&mut data, |l| l.name.clone());
    Ok(Json(LanguageList { data }))
}

#[utoipa::path(
    get,
    path = "/reference/timezones",
    operation_id = "listReferenceTimezones",
    tag = "Reference",
    summary = "Timezones the user can pick, ordered by id",
    responses((status = 200, description = "The timezones.", body = TimezoneList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("user")), ("x-inventory" = json!(["R212"])), ("x-services" = json!([])))
)]
pub async fn list_reference_timezones(
    State(_state): State<AppState>,
    Auth(_id): Auth,
) -> ApiResult<Json<TimezoneList>> {
    let data = timezones().iter().map(|z| Timezone { id: z.clone(), utc_offset: utc_offset(z) }).collect();
    Ok(Json(TimezoneList { data }))
}

/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_reference_currencies))
        .routes(routes!(list_reference_countries))
        .routes(routes!(list_reference_languages))
        .routes(routes!(list_reference_timezones))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_sets_load() {
        assert_eq!(countries().len(), 250);
        assert!(countries().iter().all(|c| c.code.len() == 2 && c.names.contains_key("eng")));
        assert_eq!(languages().len(), 185);
        assert!(
            timezones().iter().all(|z| z == "GMT" || z == "UTC" || z.parse::<chrono_tz::Tz>().is_ok()),
            "chrono-tz knows every zone"
        );
        assert_eq!(currency_name("EUR"), "Euro");
        assert_eq!(currency_name("XXX"), "currencies.XXX");
    }

    #[test]
    fn names_countries_in_the_locale() {
        let fr = countries().iter().find(|c| c.code == "DE").unwrap();
        assert_eq!(country_name(fr, iso639_3("fr")), "Allemagne");
        assert_eq!(country_name(fr, iso639_3("pt_BR")), "Alemanha");
        assert_eq!(country_name(fr, iso639_3("tr")), "Germany");
        assert_eq!(utc_offset("UTC"), 0);
        assert_eq!(utc_offset("Asia/Kolkata"), 330);
    }
}
